void MasteringEditor::addSwitch(const char* id,int x,int y,int w,int h){Switch s;s.id=id;s.area={static_cast<float>(x),static_cast<float>(y),static_cast<float>(w),static_cast<float>(h)};s.button=std::make_unique<juce::TextButton>();s.button->setButtonText(juce::String(id).endsWith("On")?juce::String::fromUTF8("⏻"):"");s.button->setClickingTogglesState(true);s.button->setColour(juce::TextButton::buttonColourId,juce::Colour(0xff51312c));s.button->setColour(juce::TextButton::buttonOnColourId,juce::Colour(0xffe6f2ee));s.button->setColour(juce::TextButton::textColourOnId,juce::Colours::black);s.button->setTitle(id);addAndMakeVisible(*s.button);s.attachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(processor.state,id,*s.button);switches.push_back(std::move(s));}
void MasteringEditor::resized(){if(sliders.size()!=controlSpecs().size()||monitors.size()!=5)return;const float sx=getWidth()/2048.f,sy=(getHeight()-52.f)/1222.f;int i=0;for(auto& s:controlSpecs()){auto rect=juce::Rectangle<float>((s.x-s.r)*sx,(s.y-s.r)*sy,2*s.r*sx,2*s.r*sy);if(juce::String(s.id).startsWith("out"))rect={float(s.x-30)*sx,700*sy,60*sx,380*sy};sliders[static_cast<size_t>(i++)]->setBounds(rect.toNearestInt());}for(auto& s:switches)s.button->setBounds(juce::Rectangle<float>(s.area.getX()*sx,s.area.getY()*sy,s.area.getWidth()*sx,s.area.getHeight()*sy).toNearestInt());const std::array<juce::Rectangle<float>,5> r{{{1754,458,115,42},{1665,458,72,42},{1887,458,72,42},{1754,512,115,42},{1887,512,72,42}}};for(int j=0;j<5;++j)monitors[static_cast<size_t>(j)]->setBounds(juce::Rectangle<float>(r[j].getX()*sx,r[j].getY()*sy,r[j].getWidth()*sx,r[j].getHeight()*sy).toNearestInt());track.setBounds(juce::Rectangle<float>(286*sx,1164*sy,351*sx,40*sy).toNearestInt());bypass.setBounds(getWidth()-168,getHeight()-39,78,26);reset.setBounds(getWidth()-84,getHeight()-39,70,26);}
void MasteringEditor::timerCallback(){const auto toDb=[](float p){return std::clamp(20.f*std::log10(std::max(p,1e-6f)),-60.f,6.f);};levelL=std::max(toDb(processor.peakL.load()),levelL-1.5f);levelR=std::max(toDb(processor.peakR.load()),levelR-1.5f);const int mode=static_cast<int>(processor.state.getRawParameterValue("monitor")->load());for(int i=0;i<5;++i)monitors[static_cast<size_t>(i)]->setToggleState(mode==i,juce::dontSendNotification);repaint();}
void MasteringEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff18242b));g.drawImage(face,{0.f,0.f,float(getWidth()),getHeight()-52.f});const float sx=getWidth()/2048.f,sy=(getHeight()-52.f)/1222.f;const float lv[2]{levelL,levelR};for(int c=0;c<2;++c){const float x=(c?1942.f:1848.f)*sx;g.setColour(juce::Colour(0xff0b170b));g.fillRect(x,670*sy,25*sx,412*sy);for(int j=0;j<54;++j){const float db=-60+j*66.f/54;g.setColour(db<=lv[c]?(db>0?juce::Colours::red:db>-6?juce::Colours::yellow:juce::Colour(0xff90ed18)):juce::Colour(0xff152c0a));g.fillRect(x+3*sx,(1077-j*7.5f)*sy,19*sx,5.5f*sy);}g.setColour(juce::Colour(0xff172229));g.fillRect((c?1925.f:1830.f)*sx,1095*sy,63*sx,36*sy);g.setColour(juce::Colour(0xffa7ed39));g.setFont(15*sx);g.drawText(juce::String(lv[c],1),int((c?1925:1830)*sx),int(1095*sy),int(63*sx),int(36*sy),juce::Justification::centred);}
 // Draw an automation indicator over each photographic control; the faceplate stays faithful to the supplied reference.
 for(size_t i=0;i<sliders.size();++i){const auto& s=controlSpecs()[i];const float t=static_cast<float>(sliders[i]->valueToProportionOfLength(sliders[i]->getValue()));g.setColour(juce::Colour(0xffbde7ed));if(juce::String(s.id).startsWith("out")){const float y=(1045-330*t)*sy;g.fillRoundedRectangle((s.x-10)*sx,y,20*sx,32*sy,2);}else{const float a=(-135+270*t)*float(tg::pi/180),radius=s.r*.62f;const juce::Point<float> centre{s.x*sx,s.y*sy};g.drawLine(centre.x+std::sin(a)*(radius-10)*sx,centre.y-std::cos(a)*(radius-10)*sy,centre.x+std::sin(a)*radius*sx,centre.y-std::cos(a)*radius*sy,2.f);}}
 // Replace the reference's fixed gain-reduction reading with the live value.
 g.setColour(juce::Colour(0xffd0cbb4));g.fillRoundedRectangle(876*sx,724*sy,51*sx,247*sy,5);const float reduction=std::clamp(processor.reduction.load(),0.f,24.f);g.setColour(juce::Colour(0xffa33e31));g.fillRect(881*sx,(730+reduction*9)*sy,41*sx,3*sy);g.setColour(juce::Colour(0xff30342d));g.setFont(12*sx);g.drawText(juce::String(-reduction,1)+" dB",int(876*sx),int(819*sy),int(51*sx),int(30*sy),juce::Justification::centred);
 g.setColour(juce::Colour(0xffb5c9d1));g.setFont(12);g.drawText(readout,14,getHeight()-45,getWidth()-200,20,juce::Justification::centredLeft);g.setColour(juce::Colour(0xff8398a2));g.setFont(9);g.drawText("TEIEM TG • Independent DSP approximation • ST / DUO / MS faceplate labels are reference artwork",14,getHeight()-24,getWidth()-200,15,juce::Justification::centredLeft);
}
